package vn.svframe.mmocorefabric.runtime.gameplay;
import java.util.*;import vn.svframe.mmocorefabric.runtime.progression.LegacyClassDefinition;
public final class ClassRuntime {private final Map<String,LegacyClassDefinition> defs=new LinkedHashMap<>();private final Map<UUID,String> selected=new HashMap<>();public synchronized void register(String id,LegacyClassDefinition d){defs.put(norm(id),d);}public synchronized void clearDefinitions(){defs.clear();}public synchronized boolean select(UUID p,String id,int level){LegacyClassDefinition d=defs.get(norm(id));if(d==null||level>d.maxLevel())return false;selected.put(p,norm(id));return true;}public synchronized void restoreSelection(UUID p,String id){if(id==null||id.isBlank())selected.remove(p);else selected.put(p,norm(id));}public synchronized Optional<String> selected(UUID p){return Optional.ofNullable(selected.get(p));}public synchronized Map<String,LegacyClassDefinition> definitions(){return Map.copyOf(defs);}public synchronized double attribute(UUID p,String key,int level){LegacyClassDefinition d=defs.get(selected.get(p));if(d==null)return 0;var a=d.attributes().get(key);return a==null?0:a.at(level);}private static String norm(String s){return s.trim().toLowerCase(Locale.ROOT);}}
